import{_ as t,o as i,c as a,al as s}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Hardware Bench Testing (px4bench)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test_and_ci/bench_testing.md","filePath":"zh/test_and_ci/bench_testing.md"}'),n={name:"zh/test_and_ci/bench_testing.md"};function r(o,e,h,l,d,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="hardware-bench-testing-px4bench" tabindex="-1">Hardware Bench Testing (px4bench) <a class="header-anchor" href="#hardware-bench-testing-px4bench" aria-label="Permalink to &quot;Hardware Bench Testing (px4bench)&quot;">​</a></h1><p>px4bench is the PX4 toolkit for automated verification on real flight-controller hardware. It qualifies a firmware build on a board sitting on a bench: no props, no airframe, just a USB cable and optionally a telemetry radio.</p><p>Use this guide if you are:</p><ul><li><strong>Qualifying a release</strong>: verify a release candidate on real NuttX hardware before cutting a branch or handing a beta to a test team.</li><li><strong>Sanity-checking a change</strong>: prove that a PR or local build boots, communicates, stores parameters and missions, and survives reboots on a real board.</li><li><strong>Testing flight logic hardware-in-the-loop</strong>: fly a full auto mission in simulation on the FMU itself (SIH) and verify arming, takeoff, mission progression, landing, and disarm on real RTOS scheduling.</li><li><strong>Running end-of-line checks in production</strong>: manufacturers can run the same suite against every unit that comes off the line, with machine-readable pass/fail results and full firmware traceability per unit.</li></ul><p>The toolkit lives in the PX4-Autopilot source tree at <a href="https://github.com/PX4/PX4-Autopilot/tree/main/Tools/bench_test" target="_blank" rel="noreferrer"><code>Tools/bench_test/</code></a>, and its <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/bench_test/README.md" target="_blank" rel="noreferrer">README</a> is the complete reference. This page explains what it does and how to apply it.</p><h2 id="why-bench-testing" tabindex="-1">Why Bench Testing <a class="header-anchor" href="#why-bench-testing" aria-label="Permalink to &quot;Why Bench Testing&quot;">​</a></h2><p>CI builds every NuttX target but never boots one, and <a href="./../simulation/">SITL</a> runs flight code on a host operating system whose threading, scheduling, and C library behave differently from the RTOS on a flight controller. Some defects therefore only exist on real hardware: boot-time initialization ordering, link lifecycle across USB re-enumeration, storage and filesystem behavior, loop-rate drift, and concurrency bugs that are invisible on a desktop OS. A build can pass every SITL test and still ship with a dead telemetry link.</p><p>Failures on embedded targets are frequently silent hangs rather than crashes, so px4bench is built around one rule: <strong>every operation has a timeout, and a timeout is reported as a failure naming exactly what stalled</strong>. Every check prints <code>[PASS]</code> or <code>[FAIL]</code>, every test exits nonzero on failure, and every run writes a timestamped report directory containing the raw evidence.</p><h2 id="firmware-traceability" tabindex="-1">Firmware Traceability <a class="header-anchor" href="#firmware-traceability" aria-label="Permalink to &quot;Firmware Traceability&quot;">​</a></h2><p>Qualification means knowing what you tested. Before any test runs, the suite reads the board&#39;s identity (git hash, version, hardware) and records it in <code>firmware.json</code> in every report directory. You state where the firmware under test comes from, and the suite verifies the flashed board actually reports the expected git hash:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># flash a local .px4 file, verify its identity, then test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --firmware</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6xrt_default.px4</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># build the current source tree for the connected board, flash, verify, test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># download a GitHub release artifact, flash, verify, test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.17.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># no flashing: assert the board already runs the expected build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expect-hash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0c000d59</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># explicit opt-out: test whatever is on the board (still recorded)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --any-firmware</span></span></code></pre></div><p>Run interactively with none of these flags, the suite shows what is on the board and asks what to do. Run non-interactively (CI, production scripting), it refuses to start without an explicit firmware expectation, so automation can never silently test the wrong build.</p><p>With <code>--build</code>, the gate also prints a bench capability report before compiling: whether the image will contain <code>simulator_sih</code>, <code>sd_bench</code>, <code>sd_stress</code>, and <code>serial_test</code>, and which suite tests will therefore run or skip. For anything missing it names a sibling board variant that includes it (for example <code>--target px4_fmu-v6xrt_bench</code>) and the exact config line, and can append the line to your local board config on request (the edit stays local and uncommitted).</p><h2 id="the-bench-suite" tabindex="-1">The Bench Suite <a class="header-anchor" href="#the-bench-suite" aria-label="Permalink to &quot;The Bench Suite&quot;">​</a></h2><p>The tests under <code>bench/</code> run against normal firmware and never arm the vehicle. The default suite sequence is <code>boot_health</code>, <code>param_stress</code>, <code>mission_stress</code> (plus <code>link_forwarding</code> when a second link is given), <code>storage_stress</code>, <code>log_transfer</code>, <code>reboot_loop</code>, and finally the simulated SIH flight (see below), which does arm and therefore sits behind a confirmation. Tests that need a firmware feature the build does not contain probe for it over the shell and record SKIP with a warning instead of failing.</p><table tabindex="0"><thead><tr><th>Test</th><th>What it verifies</th></tr></thead><tbody><tr><td><code>boot_health</code></td><td>System snapshot over the MAVLink shell: no task in error state, required work queues present, uORB topics publishing. Has a baseline mode (see below).</td></tr><tr><td><code>reboot_loop</code></td><td>Repeated reboot/reconnect cycles; catches boards that boot once but not every time.</td></tr><tr><td><code>usb_replug</code></td><td>USB unplug/replug cycles (operator-assisted); catches link-teardown leaks in mavlink instance count or RAM.</td></tr><tr><td><code>link_forwarding</code></td><td>Simultaneous heavy traffic on two links with forwarding; catches deadlocks and stalls in the MAVLink send path. Requires a second link.</td></tr><tr><td><code>param_stress</code></td><td>Full parameter download, 50 set/readback cycles, save, reboot, persistence verification.</td></tr><tr><td><code>mission_stress</code></td><td>Repeated 220-waypoint upload/download/compare/clear transactions, alternating links when two are available.</td></tr><tr><td><code>storage_stress</code></td><td>SD card health via the firmware&#39;s own <code>sd_bench</code> and <code>sd_stress</code>: write/read throughput, fsync latency, file churn. Skips without an SD card.</td></tr><tr><td><code>log_transfer</code></td><td>Short log capture, MAVFTP download, ULog integrity verification.</td></tr><tr><td><code>flight_mission</code></td><td>Simulated SIH flight on the FMU, last in the sequence; arms behind a confirmation (<code>--allow-arming</code> for automation).</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tools/bench_test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # everything, single link</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expect-hash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">has</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # + radio: adds dual-link tests</span></span></code></pre></div><p>A per-test watchdog turns a hung board into a named failure instead of a stuck terminal.</p><h2 id="simulated-flight-on-the-fmu-sih" tabindex="-1">Simulated Flight on the FMU (SIH) <a class="header-anchor" href="#simulated-flight-on-the-fmu-sih" aria-label="Permalink to &quot;Simulated Flight on the FMU (SIH)&quot;">​</a></h2><p><code>sih/flight_mission.py</code> performs a complete hardware-in-the-loop flight without any host-side simulator: it switches the board to a <a href="./../sim_sih/">SIH airframe</a> (<code>SYS_HITL=2</code>, physics computed on the autopilot), uploads a mission, arms through the NuttX shell, and asserts takeoff, waypoint progression, RTL, landing, and auto-disarm against per-phase timeouts. It runs as the last test of the default bench suite and also works standalone. Because it arms the flight controller, the suite asks for explicit confirmation on a terminal (type <code>arm</code>), and non-interactive runs skip it unless <code>--allow-arming</code> is passed. It first probes the running firmware for the SIH module and records a skip, not a failure, when the build does not include it. The flight log is downloaded into the report directory automatically for post-flight analysis, and the original board configuration is restored afterwards.</p><p>Real outputs are replaced by <code>pwm_out_sim</code> in this mode, so nothing is driven on the output rails; still, run it only on a bare bench board with nothing connected to the outputs. The firmware must be built with <code>CONFIG_MODULES_SIMULATION_SIMULATOR_SIH=y</code> (boards may provide a bench variant that adds it, such as <code>px4_fmu-v6xrt_bench</code>).</p><h2 id="baseline-comparison" tabindex="-1">Baseline Comparison <a class="header-anchor" href="#baseline-comparison" aria-label="Permalink to &quot;Baseline Comparison&quot;">​</a></h2><p><code>boot_health</code> can diff two report directories, comparing uORB publication rates, work queues, and topics between runs:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bench/boot_health.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # capture (prints report dir)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... flash a different build ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bench/boot_health.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bench/boot_health.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --baseline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # FAIL on rate drift or lost topics</span></span></code></pre></div><p>This supports two workflows:</p><ul><li><strong>Upgrade regression</strong>: capture on the current release, capture on the candidate, diff. A control-loop rate that quietly dropped between versions is a finding long before it becomes mushy flight behavior.</li><li><strong>Golden unit</strong> (manufacturing): capture a known-good reference unit once, then diff every produced unit against it. A board with a marginal sensor or misloaded configuration deviates from the golden baseline even when it nominally boots.</li></ul><h2 id="production-end-of-line-usage" tabindex="-1">Production End-of-Line Usage <a class="header-anchor" href="#production-end-of-line-usage" aria-label="Permalink to &quot;Production End-of-Line Usage&quot;">​</a></h2><p>For manufacturers the suite is designed to run unattended per unit:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_bench_suite.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PORT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --firmware</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RELEASE_PX4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --report-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;reports/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SERIAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;UNIT </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SERIAL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FAILED&quot;</span></span></code></pre></div><ul><li>Exit code is the verdict: <code>0</code> all checks passed, nonzero otherwise, with the failing check named in the output.</li><li>A skipped test does not fail the suite (individual tests exit <code>75</code> for SKIP), but a skip is absent coverage, not a pass: production procedures should treat unexpected SKIP lines in the summary as findings. Fixture design (SD card present, <code>--allow-arming</code> set, firmware built with the needed modules per the capability report) determines which tests are expected to run.</li><li><code>reports/&lt;serial&gt;/</code> retains the full evidence per unit: firmware identity, system snapshot, parameter and mission transaction results, downloaded logs.</li><li>The firmware gate guarantees each unit was tested against the intended production image, not whatever was in flash.</li><li>Pass <code>--allow-arming</code> so the simulated flight runs unattended (the line fixture must leave the output rails unconnected).</li><li><code>usb_replug</code> (connector/enumeration exercise) and <code>serial_loopback</code> (UART verification through a loopback jumper on the fixture) are operator/fixture-assisted and can be added where the procedure includes a connector or UART check.</li></ul><h2 id="ci-integration" tabindex="-1">CI Integration <a class="header-anchor" href="#ci-integration" aria-label="Permalink to &quot;CI Integration&quot;">​</a></h2><p>The suite is built to sit behind a self-hosted runner with a board permanently attached: non-interactive runs demand an explicit firmware source, all results are machine-readable exit codes plus report artifacts, and a wedged board fails fast with a named check rather than hanging the job. Pairing <code>--build</code> (current revision) with the bench suite plus a SIH flight closes the gap where CI compiles NuttX firmware without ever executing it.</p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/bench_test/README.md" target="_blank" rel="noreferrer"><code>Tools/bench_test/README.md</code></a>: complete reference (all flags, per-test details, troubleshooting, how to add a test)</li><li><a href="./../sim_sih/hardware">SIH on Hardware</a></li><li><a href="./../test_and_ci/test_flights">Test Flights</a>: real flight testing, which bench testing complements but does not replace</li></ul>`,34)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
